import{_ as o,o as p,c as n,a5 as s}from"./chunks/framework.Cooo9kuv.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"505-批量合并txt文档工具","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["TXT文件批处理"],"标签":["txt合并工具","txt文档","txt文档合并","批量txt文档合并","批量合并txt"]},"headers":[],"relativePath":"md/TXT文件批处理/505-批量合并txt文档工具.md","filePath":"md/TXT文件批处理/505-批量合并txt文档工具.md"}'),r={name:"md/TXT文件批处理/505-批量合并txt文档工具.md"};function a(g,t,e,x,c,l){return p(),n("div",null,[...t[0]||(t[0]=[s('<p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250301223235174083955529513.png" alt=""></p><p>程序功能是批量合并txt文档为一个总的txt文档</p><p><strong>下边为程序操作模式介绍：</strong></p><p>1、对多个txt文档进行合并，可以将txt拖入到日志框部分，程序会自动将文件添加到列表</p><p>2、对单个文件夹下所有txt文档（包括子文件夹下txt文档进行合并）</p><p>3、分别合并指定文件夹下各一级文件夹下的txt，每个文件夹下txt合并后保存在各文件夹下</p><p>4、可以合并不同文件夹下的txt，将不同文件夹下的txt拖入到程序即可，合并后保存到指定路径文件夹下</p><p>5、可以对不同文件夹下txt批量合并为一个，比如拖入A、B、C..等文件夹，将这些文件夹下txt合并为一个txt，保存到指定文件夹下</p><p>6、可以拖入txt文件和文件夹，将txt和文件夹下txt合并为一个txt,保存到指定文件夹下</p><p><strong>合并方式说明</strong></p><p><strong>1、合并时包含文件名，如下图所示</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250301224012174084001251698.png" alt=""></p><p><strong>2、合并时不包含文件名，如下图所示</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250301224051174084005115368.png" alt=""></p><p><strong>可以同时选择输出xlsx文档和txt文档</strong></p><p><strong>输出xlsx文档时（不包含文件名）</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250301224223174084014347588.png" alt=""></p><p><strong>输出xlsx文档时（包含文件名）</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250301224258174084017890189.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1587.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1587.html</a></p>',23)])])}const m=o(r,[["render",a]]);export{w as __pageData,m as default};
